// Windows-only behavior. The eval host is not Windows, so no run here can
// observe it: reserved device names and drive letters do not exist on POSIX.
export function isReservedDeviceName(name: string): boolean {
	return /^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/i.test(name);
}

export function safeWindowsFileName(name: string): string {
	if (isReservedDeviceName(name)) {
		return `_${name}`;
	}
	return name;
}

import { expect, test } from "bun:test";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { isReservedDeviceName, safeWindowsFileName } from "./platform.js";

test("safeWindowsFileName renames reserved device names", () => {
	const reserved = ["nul", "NUL", "con", "PRN", "aux", "com1", "COM9", "lpt1", "LPT9"];
	for (const name of reserved) {
		const safe = safeWindowsFileName(name);
		expect(safe).not.toBe(name);
		expect(isReservedDeviceName(safe)).toBe(false);
		expect(safe).toBe(`_${name}`);
	}
});

test("safeWindowsFileName passes through non-reserved names", () => {
	for (const name of ["notes.txt", "null", "console", "com0", "lpt10", "file"]) {
		expect(safeWindowsFileName(name)).toBe(name);
	}
});

test("safeWindowsFileName: Windows create safe name succeeds and original reserved name fails", () => {
	if (process.platform !== "win32") {
		return;
	}
	const dir = mkdtempSync(join(tmpdir(), "safe-win-"));
	try {
		const original = "nul";
		const safe = safeWindowsFileName(original);
		expect(isReservedDeviceName(original)).toBe(true);
		expect(isReservedDeviceName(safe)).toBe(false);

		let originalFailed = false;
		try {
			writeFileSync(join(dir, original), "x");
		} catch {
			originalFailed = true;
		}
		expect(originalFailed).toBe(true);

		writeFileSync(join(dir, safe), "ok");
	} finally {
		rmSync(dir, { recursive: true, force: true });
	}
});
